import hashlib,json,pathlib
roots=[pathlib.Path('products/services/sqlite-repair/bespoke-inbound'),pathlib.Path('products/distribution/sqlite-community-directory')]
for root in roots:
    files=[]
    for path in sorted(root.glob('*')):
        if path.is_file():
            data=path.read_bytes()
            files.append({'path':str(path),'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()})
    print(json.dumps({'root':str(root),'files':files}))
